import manifest from "@/data/project-media.generated.json";
import { assetPath } from "@/lib/asset-path";

export interface ProjectMedia {
  type: "image" | "video";
  src: string;
  name: string;
}

const projects = manifest as Record<string, readonly ProjectMedia[]>;

/** The manifest is generated by npm run dev/build; no filesystem reaches the browser. */
export function getProjectMedia(slug: string): ProjectMedia[] {
  const media = Object.hasOwn(projects, slug) ? projects[slug] : [];
  return media.map((media) => ({
    ...media,
    src: assetPath(media.src),
  }));
}
